import{_ as o,o as t,c as r,a6 as n}from"./chunks/framework.ZMCvXf1_.js";const m=JSON.parse('{"title":"noorm sql","description":"","frontmatter":{},"headers":[],"relativePath":"cli/sql.md","filePath":"cli/sql.md"}'),c={name:"cli/sql.md"};function d(a,e,s,l,i,u){return t(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="noorm-sql" tabindex="-1">noorm sql <a class="header-anchor" href="#noorm-sql" aria-label="Permalink to “noorm sql”">​</a></h1><p>Execute SQL statements and manage query history from the command line.</p><p>The <code>sql</code> namespace groups four subcommands:</p><table tabindex="0"><thead><tr><th>Subcommand</th><th>Purpose</th></tr></thead><tbody><tr><td><code>query</code></td><td>Run a SQL statement against the active config</td></tr><tr><td><code>history</code></td><td>Show recent queries (with rows and timings)</td></tr><tr><td><code>clear</code></td><td>Clear the saved query history</td></tr><tr><td><code>repl</code></td><td>Launch the TUI directly on the SQL Terminal screen</td></tr></tbody></table><h2 id="running-a-single-query" tabindex="-1">Running a single query <a class="header-anchor" href="#running-a-single-query" aria-label="Permalink to “Running a single query”">​</a></h2><h3 id="canonical-form" tabindex="-1">Canonical form <a class="header-anchor" href="#canonical-form" aria-label="Permalink to “Canonical form”">​</a></h3><p>The explicit form is always correct and is what scripts and CI pipelines should use:</p><pre><code>noorm sql query &quot;SELECT 1&quot;
noorm sql query &quot;SELECT id, name FROM users LIMIT 10&quot;
noorm sql query --json &quot;SELECT id, name FROM users&quot;
noorm sql query -f reports/monthly.sql
</code></pre><h3 id="bare-form-convenience" tabindex="-1">Bare form (convenience) <a class="header-anchor" href="#bare-form-convenience" aria-label="Permalink to “Bare form (convenience)”">​</a></h3><p>The shorter <code>noorm sql &quot;&lt;SQL&gt;&quot;</code> form is also supported. Internally, the CLI inspects argv before handing off to citty — if the first non-flag token after <code>sql</code> looks like a SQL statement (it starts with one of <code>SELECT</code>, <code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>, <code>MERGE</code>, <code>WITH</code>, <code>CREATE</code>, <code>DROP</code>, <code>ALTER</code>, <code>TRUNCATE</code>, <code>EXEC</code>, <code>EXECUTE</code>, <code>CALL</code>, <code>SHOW</code>, <code>EXPLAIN</code>, <code>GRANT</code>, <code>REVOKE</code>, <code>COMMENT</code>, <code>PRAGMA</code>, <code>VACUUM</code>, <code>ANALYZE</code>, <code>BEGIN</code>, <code>COMMIT</code>, <code>ROLLBACK</code>, <code>SAVEPOINT</code>, or <code>USE</code>), the CLI inserts the <code>query</code> subcommand for you:</p><pre><code>noorm sql &quot;SELECT 1&quot;                # → noorm sql query &quot;SELECT 1&quot;
noorm sql --json &quot;SELECT 1 AS one&quot;  # → noorm sql query --json &quot;SELECT 1 AS one&quot;
</code></pre><p>The rewrite is purely positional — it never modifies the actual SQL string or flags. The real subcommands (<code>query</code>, <code>history</code>, <code>clear</code>, <code>repl</code>) are reserved words that never trigger the rewriter.</p><p>The rewriter reads the <em>first non-flag token</em> after <code>sql</code>, so a flag that takes a value puts something else there and no rewrite happens:</p><pre><code>noorm sql -f reports/monthly.sql       # → &quot;Unknown command reports/monthly.sql&quot;
noorm sql -c prod &quot;SELECT 1&quot;           # → &quot;Unknown command prod&quot;
</code></pre><p>Both need the explicit form (<code>noorm sql query -f …</code>, <code>noorm sql query -c prod &quot;…&quot;</code>). A leading <code>--json</code>, which takes no value, is fine: <code>noorm sql --json &quot;SELECT 1&quot;</code> still rewrites.</p><h3 id="flags-on-query" tabindex="-1">Flags (on <code>query</code>) <a class="header-anchor" href="#flags-on-query" aria-label="Permalink to “Flags (on query)”">​</a></h3><ul><li><code>--config &lt;name&gt;</code> / <code>-c</code> — switch the active config for this invocation</li><li><code>--json</code> — print the result as JSON instead of human output</li><li><code>--file &lt;path&gt;</code> / <code>-f</code> — read SQL from a file</li></ul><blockquote><p><code>--json</code> is per-subcommand — place it after <code>query</code> (<code>noorm sql query &quot;…&quot; --json</code>), not before <code>sql</code>. See <a href="./flags.html">CLI flag conventions</a> for the full rule.</p></blockquote><h2 id="sibling-commands" tabindex="-1">Sibling commands <a class="header-anchor" href="#sibling-commands" aria-label="Permalink to “Sibling commands”">​</a></h2><p>For interactive use and history management:</p><ul><li><a href="./sql-repl.html"><code>noorm sql repl</code></a> — launch the TUI on the SQL terminal screen</li><li><code>noorm sql history</code> — list recent queries (<code>-n</code>/<code>--limit</code>, default 50). Only the interactive SQL terminal records history; <code>sql query</code> deliberately writes none.</li><li><code>noorm sql clear --yes</code> — wipe the saved history (<code>--older-than &lt;months&gt;</code> to keep recent entries). Without <code>--yes</code> it prints what it would clear and exits without clearing.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><pre><code># One-off query against the active config
noorm sql query &quot;SELECT count(*) FROM users&quot;

# Same thing, bare form
noorm sql &quot;SELECT count(*) FROM users&quot;

# Run a SQL file (CI-friendly)
noorm sql query -f reports/monthly.sql --json

# Pick a different config
noorm sql query -c prod &quot;SELECT count(*) FROM orders&quot;
</code></pre>`,23)])])}const q=o(c,[["render",d]]);export{m as __pageData,q as default};
